const escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function createEventsPage(root,{portrait,onRegion}){
 let data=null,category='all',query='',access='all';
 const link=(url,text)=>`<a href="${escape(url)}" target="_blank" rel="noopener noreferrer">${escape(text)} ↗</a>`;
 function matches(e){return(category==='all'||e.primary===category||e.related.includes(category))&&(access==='all'||(access==='stages'?e.stageAvailable:!e.stageAvailable))&&(!query||[e.title,e.lineTitle,e.summary,data.categories.find(c=>c.id===e.primary)?.name,...e.related.map(id=>data.categories.find(c=>c.id===id)?.name)].join(' ').toLowerCase().includes(query.toLowerCase()));}
 function renderResults(){
  const events=data.events.filter(matches),selected=data.categories.find(c=>c.id===category);
  root.querySelector('#event-count').textContent=`${events.length} 个故事`;
  root.querySelector('#event-selection').innerHTML=selected?`<span class="eyebrow">${escape(selected.kind)}</span><h2>${escape(selected.name)}</h2><p>${escape(selected.description)}</p>${selected.region?`<button data-event-map="${escape(selected.region)}">在大地图中查看 ↗</button>`:''}`:'<span class="eyebrow">STORY DIRECTORY</span><h2>从一片土地，走进一条故事线。</h2><p>按主要归属整理，保留关联地区。系列内沿用曲谱资料索引顺序，不作为剧情发生时间线；同一故事只收录一次。</p>';
  const groups=data.lines.map(l=>({...l,events:events.filter(e=>e.line===l.id)})).filter(l=>l.events.length);
  root.querySelector('#event-results').innerHTML=groups.length?groups.map(l=>`<section class="event-line"><header><div><span class="eyebrow">${escape(l.id)} / ${l.official?'游戏曲谱':'补充目录 · 非官方乐章'}</span><h3>${escape(l.title)}</h3></div><span>${l.events.length} 个故事</span></header><div class="event-cards">${l.events.map(e=>{
   const c=data.categories.find(c=>c.id===e.primary);
   return `<article class="event-card"><div class="event-card-top"><span class="event-order">${String(e.order+1).padStart(2,'0')}</span><span class="event-access ${e.stageAvailable?'with-stages':''}">${e.collaboration?'已解锁剧情可回顾':e.stageAvailable?'剧情回顾 · 常驻关卡':'剧情回顾'}</span></div><h4>${escape(e.title)}</h4><button class="event-owner" data-event-category="${escape(c.id)}">${escape(c.kind)} / ${escape(c.name)}</button><p>${escape(e.summary)}</p>${e.related.length?`<div class="event-related">关联 ${e.related.map(id=>{const r=data.categories.find(c=>c.id===id);return `<button data-event-category="${escape(id)}">${escape(r.name)}</button>`;}).join('')}</div>`:''}<details><summary>阅读入口与归类依据</summary><p>游戏内：${e.collaboration?'情报处理室／对应回顾条目':'终端 → 曲谱'} → ${escape(e.title)}。${e.collaboration?'需此前已解锁对应剧情；未参加的账号不保证能够补解锁。':'需满足账号解锁条件；故事集可能需要事相碎片。'}${e.stageAvailable?'关卡已收录常驻，仍需满足账号解锁条件。':'此处确认剧情收录，不代表战斗关卡或活动奖励当前开放。'}</p><p>${escape(e.basis)}</p><div class="event-source-links">${e.sources.map(s=>link(s.url,s.title)).join('')}</div></details></article>`;
  }).join('')}</div></section>`).join(''):'<div class="event-empty"><h3>没有找到符合条件的故事</h3><p>试试活动名、国家或组织名称，或清除筛选。</p><button data-event-reset>清除筛选</button></div>';
  root.querySelectorAll('[data-event-category]').forEach(b=>{b.classList.toggle('active',b.dataset.eventCategory===category);b.setAttribute('aria-pressed',String(b.dataset.eventCategory===category));});
 }
 function render(){
  root.innerHTML=`<div class="events-wrap"><header class="events-intro"><div><span class="eyebrow">TERRA / STORIES BEYOND THE MAIN THEME</span><h1>大地上的故事</h1><p>国家、地区与组织，将散落的活动串成一条线。</p></div><div class="events-stamp">国服 · 曲谱档案<br><strong>${data.events.length}</strong> 个故事 / ${data.lines.filter(l=>l.official).length} 条乐章 + 补充目录<br><small>核对日期 ${escape(data.checked)}</small></div></header><div class="event-featured"><button data-event-category="babel" class="event-feature babel"><div><span class="eyebrow">RL / 方舟</span><h2>巴别塔</h2><p>从往昔的理想到罗德岛的旅程</p><span>查看这一条线 →</span></div><div class="event-feature-portrait">${portrait('特蕾西娅')}</div></button><button data-event-category="kjerag" class="event-feature kjerag"><div><span class="eyebrow">KJ / 山雪与银铁</span><h2>谢拉格</h2><p>风雪、列车与圣山之下的变革</p><span>查看这一条线 →</span></div><div class="event-feature-portrait">${portrait('银灰')}</div></button></div><div class="event-scope"><span>阅读指南</span><p>收录已经进入曲谱的活动剧情；“可回顾”不等于当期奖励开放。分类是本站阅读索引，组织与国家不是同一种归属。已开放回顾的联动单独收录；尚未开放回顾的限时内容不混入可回顾目录。</p><details><summary>范围与来源</summary><p>${escape(data.scope)}</p>${data.sources.map(s=>link(s.url,s.title)).join(' · ')}</details><details class="event-unavailable"><summary>暂不计入可回顾目录的活动（${data.excluded.length}）</summary><p>核对日：${escape(data.checked)}。${data.excluded.map(e=>escape(e.title)).join('、')}。</p><p>《月行水上》战斗关卡已于2026年9月18日结束；公告与游戏表列明9月25日活动结束后开放剧情回顾，目前不算常驻可读。</p>${link('https://ak.hypergryph.com/news/9681','月行水上 · 官方开放说明')}</details></div><div class="event-browser"><aside class="event-filter" aria-label="活动归属筛选"><button data-event-category="all" class="active">全部故事 <span>${data.events.length}</span></button>${['组织','国家／地区','跨地区'].map(kind=>`<h3>${kind}</h3>${data.categories.filter(c=>c.kind===kind&&data.events.some(e=>e.primary===c.id||e.related.includes(c.id))).map(c=>`<button data-event-category="${escape(c.id)}">${escape(c.name)}<span>${data.events.filter(e=>e.primary===c.id||e.related.includes(c.id)).length}</span></button>`).join('')}`).join('')}</aside><div class="event-main"><div class="event-controls"><label><span class="sr-only">搜索活动故事</span><input id="event-search" type="search" placeholder="搜索活动、国家、组织…" autocomplete="off"></label><label><span class="sr-only">活动可访问方式</span><select id="event-access"><option value="all">全部可回顾剧情</option><option value="stages">含常驻战斗关卡</option><option value="story">仅确认剧情回顾</option></select></label><button class="event-clear" data-event-reset>重置筛选</button><span id="event-count" role="status" aria-live="polite"></span></div><div id="event-selection"></div><div id="event-results"></div></div></div></div>`;
  root.querySelector('#event-search').value=query;root.querySelector('#event-access').value=access;renderResults();
 }
 root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-event-category')){category=b.dataset.eventCategory;renderResults();const behavior=matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth';if(b.closest('.event-featured')||b.closest('.event-card'))root.querySelector('.event-browser').scrollIntoView({behavior,block:'start'});const selected=root.querySelector('.event-filter button.active');if(matchMedia('(max-width:720px)').matches&&selected)selected.scrollIntoView({behavior,block:'nearest',inline:'center'});}if(b.hasAttribute('data-event-reset')){category='all';query='';access='all';render();}if(b.dataset.eventMap)onRegion(b.dataset.eventMap);});
 root.addEventListener('input',e=>{if(e.target.id==='event-search'){query=e.target.value.trim();renderResults();}});
 root.addEventListener('change',e=>{if(e.target.id==='event-access'){access=e.target.value;renderResults();}});
 return async()=>{if(data){render();return;}root.innerHTML='<div class="events-wrap" role="status">正在载入活动故事档案…</div>';try{const r=await fetch('events.json');if(!r.ok)throw Error(r.status);data=await r.json();render();}catch{root.innerHTML='<div class="events-wrap"><h1>活动档案暂时无法载入</h1><p>请检查本地服务后重新打开此页。</p></div>';}};
}
